import{getDecimalSeparator,parseLocaleFloat,formatLocaleNumber,maybeConvertAmount,isZeroDecimal,getValidPricePattern,PRICE_INPUT_PATTERN}from"../currency";describe("getDecimalSeparator",(()=>{it("returns a comma for comma locales",(()=>{expect(getDecimalSeparator("de-DE")).toBe(",")})),it("returns a dot for dot locales",(()=>{expect(getDecimalSeparator("en-US")).toBe(".")})),it("falls back to a dot for a malformed locale tag instead of throwing",(()=>{expect(getDecimalSeparator("not a locale!")).toBe(".")}))})),describe("parseLocaleFloat",(()=>{it("parses a comma decimal without silently truncating",(()=>{expect(parseLocaleFloat("9,90")).toBe(9.9),expect((100*parseLocaleFloat("9,90")).toFixed(2)).toBe("990.00")})),it("parses a dot decimal",(()=>{expect(parseLocaleFloat("9.90")).toBe(9.9)})),it("accepts a comma regardless of locale (never inflates to 992)",(()=>{const e=parseLocaleFloat("99,2");expect(e).toBe(99.2),expect(e).not.toBe(992)})),it("handles multi-separator grouping by disambiguating on the last separator",(()=>{expect(parseLocaleFloat("1.234,56")).toBe(1234.56),expect(parseLocaleFloat("1,234.56")).toBe(1234.56)})),it("treats a grouping separator followed by 3 digits as grouping, not a decimal",(()=>{expect(parseLocaleFloat("1,000","en-US")).toBe(1e3),expect(parseLocaleFloat("2,500","en-US")).toBe(2500),expect(parseLocaleFloat("10,000","en-US")).toBe(1e4),expect(parseLocaleFloat("1.000","de-DE")).toBe(1e3),expect(parseLocaleFloat("1,234,567","en-US")).toBe(1234567)})),it("parses a plain integer",(()=>{expect(parseLocaleFloat("1000")).toBe(1e3)})),it("returns NaN for non-string input",(()=>{expect(parseLocaleFloat(void 0)).toBeNaN()})),it("parses the Arabic decimal separator instead of deleting it",(()=>{expect(parseLocaleFloat("9٫90")).toBe(9.9),expect(parseLocaleFloat("9٫90")).not.toBe(990)})),it("parses Eastern Arabic-Indic digits",(()=>{expect(parseLocaleFloat("٩٫٩٠")).toBe(9.9),expect(parseLocaleFloat("١٬٠٠٠")).toBe(1e3),expect(parseLocaleFloat("١٢٣٤")).toBe(1234)})),it("parses Persian digits",(()=>{expect(parseLocaleFloat("۹٫۹۰")).toBe(9.9),expect(parseLocaleFloat("۱۰۰")).toBe(100)})),it("still tolerates whitespace grouping, apostrophe grouping and currency symbols",(()=>{expect(parseLocaleFloat("1 000,50")).toBe(1000.5),expect(parseLocaleFloat("1'000.50")).toBe(1000.5),expect(parseLocaleFloat("€9,90")).toBe(9.9),expect(parseLocaleFloat("$1,234.56")).toBe(1234.56)})),it("returns NaN for unknown characters instead of gluing digits together",(()=>{expect(parseLocaleFloat("9x90")).toBeNaN(),expect(parseLocaleFloat("9;90")).toBeNaN(),expect(parseLocaleFloat("9·90")).toBeNaN()})),it("returns NaN for structurally invalid separator use, not a plausible wrong number",(()=>{expect(parseLocaleFloat("1.2.3")).toBeNaN(),expect(parseLocaleFloat("1,2,3,4")).toBeNaN(),expect(parseLocaleFloat("1..50")).toBeNaN(),expect(parseLocaleFloat("1.234,56")).toBe(1234.56),expect(parseLocaleFloat("1,234,567")).toBe(1234567)})),it("rejects hyphens instead of truncating at them",(()=>{expect(parseLocaleFloat("9-90")).toBeNaN(),expect(parseLocaleFloat("-9.90")).toBeNaN()})),it("tolerates a bare trailing separator mid-typing",(()=>{expect(parseLocaleFloat("9,")).toBe(9),expect(parseLocaleFloat("9.")).toBe(9)})),it("rejects whitespace and currency symbols between digits instead of gluing",(()=>{expect(parseLocaleFloat("9€90")).toBeNaN(),expect(parseLocaleFloat("9 90")).toBeNaN(),expect(parseLocaleFloat("€9,90")).toBe(9.9)}))})),describe("PRICE_INPUT_PATTERN / parseLocaleFloat contract",(()=>{const e=new RegExp(`^(?:${PRICE_INPUT_PATTERN})$`,"u"),t=["9.90","9,90","9٫90","٩٫٩٠","۹٫۹۰","9,",".5",",5","٫5",".99","1000","1,000","١٬٠٠٠","1,234,567","1.234,56","1,234.56","1 000,50","1'000.50","€9,90","$1,234.56"];it.each(t)("both accept %s",(t=>{expect(e.test(t)).toBe(!0),expect(parseLocaleFloat(t,"en-US")).not.toBeNaN()})),it.each(["9x90","9;90","9-90","-9.90","1.2.3","1,2,3,4","1..50","9 90","9€90",".",".555"])("both reject %s",(t=>{expect(e.test(t)).toBe(!1),expect(parseLocaleFloat(t,"en-US")).toBeNaN()})),it("never rejects what the parser accepts, for any locale",(()=>{for(const a of["en-US","de-DE","fa"])for(const o of[...t,"1.000","1.500","9.999"])isNaN(parseLocaleFloat(o,a))||expect(e.test(o)).toBe(!0)})),it("accepts everything formatLocaleNumber can emit",(()=>{for(const t of["en-US","de-DE","fa"])expect(e.test(formatLocaleNumber(1234.56,t))).toBe(!0)}))})),describe("parseLocaleFloat locale disambiguation",(()=>{it.each([["1.500","en-US",NaN],["1.500","de-DE",1500],["1,500","en-US",1500],["1,500","de-DE",NaN],["9.999","en-US",NaN],["12.345","en-US",NaN],["1٫500","fa",NaN],["1٬500","fa",1500]])("%s in %s",((e,t,a)=>{const o=parseLocaleFloat(e,t);isNaN(a)?expect(o).toBeNaN():expect(o).toBe(a)})),it("reads a bare leading decimal, as the number input it replaced did",(()=>{for(const e of["en-US","de-DE"])expect(parseLocaleFloat(".5",e)).toBe(.5),expect(parseLocaleFloat(",5",e)).toBe(.5),expect(parseLocaleFloat("٫5",e)).toBe(.5),expect(parseLocaleFloat(".",e)).toBeNaN(),expect(parseLocaleFloat(".555",e)).toBeNaN()})),it("leaves unambiguous amounts alone in every locale",(()=>{for(const e of["en-US","de-DE","fa"])expect(parseLocaleFloat("9.90",e)).toBe(9.9),expect(parseLocaleFloat("9,90",e)).toBe(9.9),expect(parseLocaleFloat("1500",e)).toBe(1500),expect(parseLocaleFloat("1,234.56",e)).toBe(1234.56)}))})),describe("getValidPricePattern",(()=>{it("returns the pattern where it compiles, so raw inputs can bind it",(()=>{expect(getValidPricePattern()).toBe(PRICE_INPUT_PATTERN)})),it("returns undefined rather than a pattern the browser would choke on",(()=>{const e=RegExp;global.RegExp=function(){throw new SyntaxError("unsupported")};try{expect(getValidPricePattern()).toBeUndefined()}finally{global.RegExp=e}}))})),describe("formatLocaleNumber",(()=>{it("uses the locale decimal separator so input matches what is displayed",(()=>{expect(formatLocaleNumber(9.9,"de-DE")).toBe("9,9"),expect(formatLocaleNumber(9.9,"en-US")).toBe("9.9")})),it("returns an empty string for NaN",(()=>{expect(formatLocaleNumber(NaN,"en-US")).toBe("")})),it('only ever emits "." or "," for non-Latin-separator locales',(()=>{expect(formatLocaleNumber(9.9,"fa")).toBe("9.9"),expect(formatLocaleNumber(9.9,"ar-EG")).toBe("9.9"),expect(parseLocaleFloat(formatLocaleNumber(9.9,"fa"))).toBe(9.9)}))})),describe("parse/format round trip",(()=>{it("is stable through convert -> format -> parse for a comma locale",(()=>{const e=formatLocaleNumber(maybeConvertAmount(990,"eur"),"de-DE");expect(e).toBe("9,9"),expect((100*parseLocaleFloat(e)).toFixed(2)).toBe("990.00")}))})),describe("isZeroDecimal",(()=>{it("detects zero-decimal currencies case-insensitively",(()=>{expect(isZeroDecimal("JPY")).toBe(!0),expect(isZeroDecimal("usd")).toBe(!1)}))}));